mapper.select:
SELECT fi.fund_code, fi.fund_name, fi.fund_type, fi.source, fi.source_updated_at, fi.business_date AS as_of_date, fi.business_date, fi.data_version, fi.quality_status, fi.quality_reason, nav.unit_nav AS latest_nav, nav.nav_date, nav.data_version AS latest_nav_data_version, nav.quality_status AS latest_nav_quality_status, nav.quality_reason AS latest_nav_quality_reason, holding.report_date AS latest_holding_report_date, holding.data_version AS latest_holding_data_version, holding.quality_status AS latest_holding_quality_status, sync.state AS sync_state, sync.state AS sync_status, sync.fetch_batch_id AS sync_fetch_batch_id, estimate.estimate_nav, estimate.estimate_growth_rate,
estimate.estimate_time AT TIME ZONE 'Asia/Shanghai' AS estimate_time, CASE WHEN estimate.estimate_time IS NULL THEN TRUE WHEN estimate.source_status != 'NORMAL' THEN TRUE WHEN estimate.estimate_time < CURRENT_TIMESTAMP - INTERVAL '3 minutes' THEN TRUE ELSE FALSE END AS stale FROM fund_info fi LEFT JOIN LATERAL ( SELECT fn.unit_nav, fn.nav_date, fn.data_version, fn.quality_status, fn.quality_reason FROM fund_nav fn WHERE fn.fund_code = fi.fund_code ORDER BY fn.nav_date DESC LIMIT 1 ) nav ON TRUE LEFT JOIN LATERAL ( SELECT fh.report_date, fh.data_version, fh.quality_status FROM fund_holding fh WHERE fh.fund_code = fi.fund_code ORDER BY fh.report_date DESC LIMIT 1 ) holding ON TRUE LEFT JOIN LATERAL ( SELECT fsr.state, fsr.fetch_batch_id FROM fund_sync_run fsr WHERE fsr.dataset IN ('FUND_INFO', 'FUND_NAV', 'FUND_HOLDING') AND (fsr.scope_value = fi.fund_code OR fsr.scope_type = 'ALL') ORDER BY fsr.started_at DESC LIMIT 1 ) sync ON TRUE LEFT JOIN LATERAL ( SELECT fe.estimate_nav, fe.estimate_growth_rate, fe.estimate_time, fe.source_status FROM fund_estimate fe WHERE fe.fund_code = fi.fund_code ORDER BY fe.estimate_time DESC LIMIT 1 ) estimate ON TRUE WHERE fi.del_flag = 0
AND fi.fund_code = #{bo.fundCode}
AND ( fi.fund_name ILIKE CONCAT('%', #{bo.fundName}, '%') OR fi.pinyin_abbr ILIKE CONCAT('%', #{bo.fundName}, '%') )
AND fi.fund_type = #{bo.fundType}
AND fi.source = #{bo.source}
AND fi.quality_status = #{bo.qualityStatus}
AND sync.state = #{bo.syncStatus}
AND fi.status = #{bo.status}
AND fi.status = '0'
ORDER BY fi.fund_code
